UPDATE decision_nodes SET data = '{"type":"question","module":3,"title":"Grade the Injury After Rewarming","body":"**Grade after rewarming:** look at how far toward the hand or foot the cyanosis (the persistent blue-grey colour) reaches. Hemorrhagic (bloody) blisters also signal deep injury.\n\n**Cauchy grade** (by the most proximal level of the lesion):\n• **0:** no lesion.\n• **1:** distal phalanx.\n• **2:** middle phalanx, or the proximal phalanx of the thumb or big toe.\n• **3:** proximal phalanx (other digits).\n• **4:** metacarpal or metatarsal.\n• **5:** carpal or tarsal.\n\nHigher grades mean more proximal injury and a greater risk of functionally important amputation. The grading is not formally validated, but it correlates well with bone scans and outcomes. [1][2]","citation":[1,2],"options":[{"label":"Grade 0-1: superficial or distal phalanx only","description":"Clear blisters, no proximal cyanosis","next":"frostbite-superficial"},{"label":"Grade 2: middle phalanx (proximal phalanx of the thumb or big toe)","description":"Deep injury short of the proximal phalanx","next":"frostbite-grade2","urgency":"urgent"},{"label":"Grade 3-5: proximal phalanx or beyond","description":"Deep injury at or proximal to the PIP joint","next":"frostbite-reperfusion","urgency":"critical"}],"images":[{"src":"images/frostbite/cauchy-grade-levels.svg","alt":"Diagram of one finger and the hand bones beside it, divided into bands from the fingertip toward the wrist: distal phalanx is grade 1, middle phalanx grade 2, proximal phalanx grade 3, metacarpal grade 4, carpal bones grade 5.","caption":"Cauchy grade by the most proximal level of the lesion after rewarming. For the thumb and big toe, the proximal phalanx counts as grade 2. (myMedKitt diagram, after the WMS frostbite guideline.)"}],"calculatorLinks":[{"id":"frostbite-cauchy","label":"Cauchy Grade"}],"summary":"Cauchy grade after rewarming: how far proximally the cyanosis reaches"}'::jsonb
