UPDATE decision_nodes SET data = '{"type":"info","module":7,"title":"Delayed Amputation","body":"**Do not amputate early.** Complete demarcation (the clear line between living and dead tissue) can take **1 to 3 months**, and early surgery removes tissue that would have survived.\n\n**Operate early only for** sepsis from infected frostbitten tissue (wet gangrene) or compartment syndrome.\n\nAngiography, a technetium bone scan or MRI helps set surgical margins together with the exam. A surgeon experienced in frostbite should make the call, by telemedicine if none is local. Involve rehabilitation early: the limb is often insensate, so footwear and orthotics matter. [1]","citation":[1],"next":"frostbite-dispo","images":[{"src":"images/frostbite/toes-frostbite-evolving.jpg","alt":"Top view of a foot with frostbitten toes: the big toe is red and swollen with a purple-grey tip and peeling skin; the smaller toes have dark, dry, crusted tips (eschar) with purple discoloration.","caption":"Frostbitten toes as the injury evolves: dark dry tips (eschar), purple-grey discoloration and red swelling; cropped. (CC0, Gerardolagunes, via Wikimedia Commons.)"}],"summary":"Wait 1-3 months for demarcation unless sepsis or compartment syndrome"}'::jsonb
